rejects(fn()=>$s->createCampaign(['name'=>'Rollback','template_id'=>$template,'contact_ids'=>$id.',99999']));
check((int)$db->query('SELECT COUNT(*) FROM advance_campaigns')->fetchColumn()===$before,'Campaña parcial revertida');
